node - <<'EOF'
const fs = require("fs");
// Run DDL under a short lock_timeout, retrying, so a waiting ACCESS EXCLUSIVE lock never queues app queries for long.
const locked = (ddl) =>
  "SET lock_timeout = '300ms'; DO $$ BEGIN FOR i IN 1..100 LOOP BEGIN " + ddl +
  " RETURN; EXCEPTION WHEN lock_not_available THEN PERFORM pg_sleep(0.2 + random() * 0.5); END; END LOOP; " +
  "RAISE EXCEPTION 'could not lock orders'; END $$;";
const env = (read, write) => ({ AMOUNT_READ: read, AMOUNT_WRITE: write, GUEST_EMAIL: "null" });
const B = 50000, MAX = 10000000;
let backfill = "SET statement_timeout = 0; SET lock_timeout = '5s';";
for (let lo = 0; lo < MAX; lo += B)
  backfill += ` UPDATE orders SET total = amount WHERE id > ${lo} AND id <= ${lo + B} AND total IS NULL;`;
backfill += ` UPDATE orders SET total = amount WHERE id > ${MAX} AND total IS NULL;`;
const plan = { task: "rename-amount", steps: [
  { note: "Expand: add nullable total (metadata only); drop NOT NULL from amount so the app can later stop writing it.",
    sql: locked("ALTER TABLE orders ADD COLUMN total numeric(10,2), ALTER COLUMN amount DROP NOT NULL;") },
  { note: "App writes both amount and total, still reads amount.", deploy: env("amount", "amount,total") },
  { note: "Let terminating old pods finish in-flight requests (3 s drain + 2 s statement timeout).", wait: 10 },
  { note: "Backfill total = amount in 50k-row primary-key ranges, each its own short transaction; then rows inserted since the seed.",
    sql: backfill },
  { note: "Make total NOT NULL without a long ACCESS EXCLUSIVE scan: NOT VALID check, validate under a non-blocking lock.",
    sql: locked("ALTER TABLE orders ADD CONSTRAINT orders_total_not_null CHECK (total IS NOT NULL) NOT VALID;") +
         " SET statement_timeout = 0; SET lock_timeout = '5s'; ALTER TABLE orders VALIDATE CONSTRAINT orders_total_not_null;" },
  { note: "SET NOT NULL uses the validated check (no scan), then the helper check is dropped.",
    sql: locked("ALTER TABLE orders ALTER COLUMN total SET NOT NULL; ALTER TABLE orders DROP CONSTRAINT orders_total_not_null;") },
  { note: "App reads total, still writes both (old pods reading amount stay correct during the rollout).", deploy: env("total", "amount,total") },
  { note: "Drain old pods.", wait: 10 },
  { note: "App reads and writes total only.", deploy: env("total", "total") },
  { note: "Drain old pods so nothing still writes amount.", wait: 10 },
  { note: "Contract: drop amount (metadata only).", sql: locked("ALTER TABLE orders DROP COLUMN amount;") },
  { note: "Reclaim the dead tuples left by the backfill (plain VACUUM, does not block the app).",
    sql: "SET statement_timeout = 0; VACUUM (ANALYZE) orders;" },
]};
fs.writeFileSync("plans/plain-rename-amount-2.json", JSON.stringify(plan, null, 2) + "\n");
console.log(plan.steps.length, "steps;", backfill.split("UPDATE").length - 1, "update batches");
EOF
